const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const airport_coords = ee.Geometry.Point(85.8177, 20.2443); // Biju Patnaik Airport
  const saheed_nagar_coords = ee.Geometry.Point(85.848691, 20.290813); // Saheed Nagar

  const start_date = '2019-04-30';
  const end_date = '2019-05-05'; // Inclusive

  const scale = 500; // VIIRS DNB has ~750m resolution, 500m is fine for point samples
  const band = 'avg_rad'; // Average Radiance band

  // 2. Data Acquisition
  const viirs_dnb_collection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG_RAW')
    .filterDate(start_date, ee.Date(end_date).advance(1, 'day')) // FilterDate is exclusive for end date
    .select(band);

  const filterAndGetImage = async (geometry, locationName) => {
    const images = viirs_dnb_collection.filterBounds(geometry);
    const numImages = await images.size().getInfo();

    if (numImages === 0) {
      console.log(`No images found for ${locationName} between ${start_date} and ${end_date}.`);
      return { initial: null, final: null, numImages: 0 };
    }

    // Get the earliest and latest image within the collection
    const firstImage = images.sort('system:time_start', true).first();
    const lastImage = images.sort('system:time_start', false).first();

    const initialBrightness = await firstImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get(band).getInfo();

    const finalBrightness = await lastImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get(band).getInfo();

    const firstImageDate = ee.Date(firstImage.get('system:time_start')).format('YYYY-MM-dd').getInfo();
    const lastImageDate = ee.Date(lastImage.get('system:time_start')).format('YYYY-MM-dd').getInfo();

    console.log(`${locationName} - Images: ${numImages}, First image date: ${firstImageDate}, Last image date: ${lastImageDate}`);

    return { initial: initialBrightness, final: finalBrightness, numImages: numImages };
  };

  let airport_data;
  let saheed_nagar_data;

  try {
    airport_data = await filterAndGetImage(airport_coords, 'Biju Patnaik Airport');
    saheed_nagar_data = await filterAndGetImage(saheed_nagar_coords, 'Saheed Nagar');
  } catch (error) {
    console.log("Error during image acquisition or reduction:", error);
    console.log("D"); // D: Syntax/method error or memory issue.
    return;
  }

  // 3. Check for C1 (Empty Collection)
  if (airport_data.numImages === 0 || saheed_nagar_data.numImages === 0) {
    console.log("C1");
    return;
  }

  const airport_initial = airport_data.initial;
  const airport_final = airport_data.final;
  const saheed_nagar_initial = saheed_nagar_data.initial;
  const saheed_nagar_final = saheed_nagar_data.final;

  // 4. Check for C3 (Calculation Failure - None, NaN)
  if (airport_initial === null || airport_final === null || saheed_nagar_initial === null || saheed_nagar_final === null ||
      isNaN(airport_initial) || isNaN(airport_final) || isNaN(saheed_nagar_initial) || isNaN(saheed_nagar_final)) {
    console.log("C3");
    return;
  }

  // 5. Calculate decrease
  const airport_decrease = airport_initial - airport_final;
  const saheed_nagar_decrease = saheed_nagar_initial - saheed_nagar_final;

  console.log(`Airport Initial Brightness: ${airport_initial.toFixed(4)} nW/cm²/sr`);
  console.log(`Airport Final Brightness:   ${airport_final.toFixed(4)} nW/cm²/sr`);
  console.log(`Airport Brightness Change:  ${airport_decrease.toFixed(4)} nW/cm²/sr`);

  console.log(`Saheed Nagar Initial Brightness: ${saheed_nagar_initial.toFixed(4)} nW/cm²/sr`);
  console.log(`Saheed Nagar Final Brightness:   ${saheed_nagar_final.toFixed(4)} nW/cm²/sr`);
  console.log(`Saheed Nagar Brightness Change:  ${saheed_nagar_decrease.toFixed(4)} nW/cm²/sr`);

  // 6. Determine the answer
  // A "decrease" means the change is positive (initial > final).
  // If the value increased, the "decrease" would be negative.
  // The question asks "decrease more than", implying we compare the magnitude of decrease.
  // If both decreased, we compare `airport_decrease > saheed_nagar_decrease`.
  // If one increased and the other decreased, or both increased, this needs careful interpretation.
  // Let's interpret "decrease more than" as:
  // (airport_initial - airport_final) > (saheed_nagar_initial - saheed_nagar_final)

  if (airport_decrease > saheed_nagar_decrease) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
